tool_input.content:
// zentao bug 6279 部署验证脚本（临时，不提交）
// 验证部署站点 http://127.0.0.1:8098 上的 :has() 回退：
//  A. 现代引擎（真实 Chromium）：html 不带 no-has-support；:has() 规则照常生效；仅表单结构仍内滚（行为不变）
//  B. 模拟老内核（stub CSS.supports→false）：html 带 no-has-support；bug 场景（仅表单）翻转为整页滚动；
//     表单+底部块结构回退值与 :has() 路径一致
import { chromium } from 'playwright'

const BASE = 'http://127.0.0.1:8098'
const results = []
const log = (name, ok, detail) => {
  results.push({ name, ok })
  console.log((ok ? 'PASS' : 'FAIL') + ' | ' + name + (detail ? ' | ' + detail : ''))
}

const browser = await chromium.launch()

// ---------- A. 现代引擎（不加 stub）----------
{
  const ctx = await browser.newContext()
  const page = await ctx.newPage()
  await page.goto(BASE + '/', { waitUntil: 'load' })
  await page.waitForSelector('#app', { timeout: 15000 })
  const hasClass = await page.evaluate(() => document.documentElement.classList.contains('no-has-support'))
  log('A1 现代: html 不带 no-has-support', hasClass === false, 'hasClass=' + hasClass)

  // A2: 表单+底部块结构 → :has() 整页滚动规则生效
  const modern2 = await page.evaluate(() => {
    const host = document.createElement('div')
    host.innerHTML = '<div class="detail-container"><div class="detail-from-container"></div><div class="collapse-container"></div></div>'
    document.body.appendChild(host)
    const dc = host.querySelector('.detail-container')
    const form = host.querySelector('.detail-from-container')
    const out = { dc: getComputedStyle(dc).overflowY, formFlex: getComputedStyle(form).flex }
    host.remove()
    return out
  })
  log('A2 现代: 带 collapse-container → :has() 规则整页滚动(auto)', modern2.dc === 'auto', JSON.stringify(modern2))

  // A3: 仅表单结构 → 基础规则 overflow:hidden（现代行为不变，即重构后语义）
  const modern3 = await page.evaluate(() => {
    const host = document.createElement('div')
    host.innerHTML = '<div class="detail-container"><div class="detail-from-container"></div></div>'
    document.body.appendChild(host)
    const out = getComputedStyle(host.querySelector('.detail-container')).overflowY
    host.remove()
    return out
  })
  log('A3 现代: 仅表单结构 → 基础 hidden（现代语义未回退）', modern3 === 'hidden', 'overflowY=' + modern3)
  await ctx.close()
}

// ---------- B. 模拟老内核（CSS.supports 对 :has 返回 false）----------
{
  const ctx = await browser.newContext()
  await ctx.addInitScript(() => {
    const orig = window.CSS && typeof window.CSS.supports === 'function' ? window.CSS.supports.bind(window.CSS) : null
    Object.defineProperty(window, 'CSS', {
      configurable: true,
      value: {
        supports: function (prop, val) {
          if (arguments.length === 1 && typeof prop === 'string' && prop.indexOf(':has(') !== -1) return false
          return orig ? orig(prop, val) : false
        },
      },
    })
  })
  const page = await ctx.newPage()
  await page.goto(BASE + '/', { waitUntil: 'load' })
  await page.waitForSelector('#app', { timeout: 15000 })
  const hasClass = await page.evaluate(() => document.documentElement.classList.contains('no-has-support'))
  log('B1 模拟老内核: html 带 no-has-support（探测→打标）', hasClass === true, 'hasClass=' + hasClass)

  // B2: bug 场景——仅表单结构。类标记在场 → 回退整页滚动 auto；移除类 → 回到基础 hidden（真实老内核即 bug 形态）
  const legacy2 = await page.evaluate(() => {
    const host = document.createElement('div')
    host.innerHTML = '<div class="detail-container"><div class="detail-from-container"></div></div>'
    document.body.appendChild(host)
    const dc = host.querySelector('.detail-container')
    const on = getComputedStyle(dc).overflowY
    document.documentElement.classList.remove('no-has-support')
    const off = getComputedStyle(dc).overflowY
    document.documentElement.classList.add('no-has-support')
    host.remove()
    return { on, off }
  })
  log('B2 模拟老内核: 仅表单结构 类标记在场 → 整页滚动(auto)', legacy2.on === 'auto', JSON.stringify(legacy2))
  log('B3 模拟老内核: 移除类标记 → 基础 hidden（证明行为由标记驱动）', legacy2.off === 'hidden', 'off=' + legacy2.off)

  // B4: 表单+底部块结构 → 回退规则生效，值与 :has() 路径一致
  const legacy4 = await page.evaluate(() => {
    const host = document.createElement('div')
    host.innerHTML = '<div class="detail-container"><div class="detail-from-container"></div><div class="collapse-container"></div></div>'
    document.body.appendChild(host)
    const dc = host.querySelector('.detail-container')
    const form = host.querySelector('.detail-from-container')
    const out = {
      dc: getComputedStyle(dc).overflowY,
      dcGutter: getComputedStyle(dc).scrollbarGutter,
      formFlex: getComputedStyle(form).flex,
      formOverflow: getComputedStyle(form).overflowY,
    }
    host.remove()
    return out
  })
  log('B4 模拟老内核: 带 collapse-container → 回退整页滚动(auto)+stable', legacy4.dc === 'auto' && legacy4.dcGutter === 'stable', JSON.stringify(legacy4))
  log('B5 模拟老内核: 表单子块 flex:0 0 auto + overflow visible', legacy4.formFlex === '0 0 auto' && legacy4.formOverflow === 'visible', JSON.stringify(legacy4))
  await ctx.close()
}

await browser.close()
const fails = results.filter((r) => !r.ok)
console.log('---')
console.log('TOTAL ' + results.length + ' | PASS ' + (results.length - fails.length) + ' | FAIL ' + fails.length)
process.exit(fails.length ? 1 : 0)

